// Detect a cycle in the Wait For Graph using depth first search.
// visiting holds nodes on the current path being explored right now.
// visited holds nodes that are fully explored and already cleared.
function hasCycle(graph) {
  const visiting = new Set();
  const visited = new Set();

  function dfs(node) {
    if (visiting.has(node)) return true;   // back edge found, a cycle exists
    if (visited.has(node)) return false;   // already cleared, nothing here
    visiting.add(node);
    for (const neighbor of graph[node]) {
      if (dfs(neighbor)) return true;
    }
    visiting.delete(node);
    visited.add(node);
    return false;
  }

  for (const node of Object.keys(graph)) {
    if (dfs(node)) return true;   // deadlock: some cycle exists in the graph
  }
  return false;   // no cycle anywhere, the system is not deadlocked
}
